package cl.bolsillo.app;
import android.widget.*;import org.json.*;import java.util.*;
final class SharesEditor {
 final Forms.Form f;final LinearLayout box;final JSONArray parts;
 SharesEditor(Forms.Form f,JSONArray old)throws Exception{this.f=f;parts=old==null?new JSONArray():new JSONArray(old.toString());box=Modern.column(f.a);f.box.addView(box);draw();}
 void draw(){box.removeAllViews();for(int i=0;i<parts.length();i++){final int index=i;JSONObject s=parts.optJSONObject(i);Modern.add(box,Modern.item(f.a,"people",s.optString("name"),"",f.a.money(s.optLong("amount")),Glass.VIOLET,()->NativeSettings.choose(f.a,s.optString("name"),Arrays.asList("Cambiar parte","Quitar"),n->{if(n==1){parts.remove(index);draw();}else edit(s,index);})),6);}NativeSettings.action(f.a,box,"Añadir persona",()->f.a.attempt(()->{JSONArray people=f.a.data.getJSONArray("people");List<String> labels=new ArrayList<>();List<JSONObject> list=new ArrayList<>();for(int i=0;i<people.length();i++){JSONObject p=people.getJSONObject(i);if(!p.optBoolean("archived")){labels.add(p.getString("name"));list.add(p);}}labels.add("+ Nueva persona");NativeSettings.choose(f.a,"Compartir con",labels,n->{if(n==list.size()){PeopleScreen.editPerson(f.a,null,p->{f.a.attempt(()->{f.a.data=LocalData.read(f.a);edit(new JSONObject().put("id",Ledger.id()).put("personId",p.getString("id")).put("name",p.getString("name")),-1);});});}else f.a.attempt(()->{JSONObject p=list.get(n);for(int j=0;j<parts.length();j++)Ledger.require(!parts.getJSONObject(j).optString("personId").equals(p.getString("id")),"Esta persona ya está añadida");edit(new JSONObject().put("id",Ledger.id()).put("personId",p.getString("id")).put("name",p.getString("name")),-1);});});}));}
 void edit(JSONObject s,int index){Forms.Form e=new Forms.Form(f.a,s.optString("name"));EditText amount=e.field("Su parte",s.optString("amount"),true);e.save("Guardar parte",()->{JSONObject part=new JSONObject(s.toString()).put("amount",Forms.amount(amount,false));if(index<0)parts.put(part);else parts.put(index,part);draw();});}
 JSONArray value()throws Exception{return new JSONArray(parts.toString());}
 long total(){long sum=0;for(int i=0;i<parts.length();i++)sum+=parts.optJSONObject(i).optLong("amount");return sum;}
}
